package app.planaloud;
import android.graphics.RectF;
import android.text.*;
import java.util.*;

/** Hard constraints first: disjoint text, disjoint leaders, obtuse elbows; then shortest nearby route. */
final class TimelineCallouts {
    static final class Label {
        final DayEvents.Segment event;final int index,side,row;final float anchor,left,right,elbow,y;final String text;final RectF textBounds;
        Label(DayEvents.Segment e,int index,int side,int row,float anchor,float left,float right,float elbow,float y,String text,RectF bounds){event=e;this.index=index;this.side=side;this.row=row;this.anchor=anchor;this.left=left;this.right=right;this.elbow=elbow;this.y=y;this.text=text;textBounds=bounds;}
    }
    static final class Layout {final List<Label> labels=new ArrayList<>();int next,above,below;}
    private static final class State {final List<Label> labels;final double cost;State(List<Label> labels,double cost){this.labels=labels;this.cost=cost;}}
    static Layout layout(List<DayEvents.Segment> events,int start,float width,TextPaint paint,float pad,float gap,float maxName){
        List<Integer> order=new ArrayList<>();for(int i=0;i<events.size();i++)order.add(i);order.sort(Comparator.comparingInt((Integer i)->events.get(i).start+events.get(i).end).thenComparingInt(i->i));start=Math.max(0,Math.min(start,order.size()));order=new ArrayList<>(order.subList(start,order.size()));float available=Math.max(1,width-2*pad),font=paint.getFontMetrics().bottom-paint.getFontMetrics().top,rowHeight=Math.max(gap*4,font+gap*2),slot=Math.max(1,(available-gap*Math.max(0,(order.size()+3)/4-1))/Math.max(1,(order.size()+3)/4));
        float[] widths={Math.min(maxName,available*.42f),Math.min(maxName,slot),Math.max(1,slot*.78f),Math.max(1,slot*.56f)};
        if(order.size()<=20)for(float limit:widths){List<State> beam=new ArrayList<>();beam.add(new State(new ArrayList<>(),0));for(int index:order){List<State> next=new ArrayList<>();for(State state:beam){List<Label> candidates=candidates(events.get(index),index,state.labels,width,paint,pad,gap,limit,rowHeight);candidates.sort(Comparator.comparingDouble(TimelineCallouts::cost));Map<String,Integer> tracks=new HashMap<>();for(Label candidate:candidates){String key=candidate.side+":"+candidate.row+":"+(candidate.elbow>candidate.anchor);int count=tracks.getOrDefault(key,0);if(count>=2)continue;tracks.put(key,count+1);List<Label> labels=new ArrayList<>(state.labels);labels.add(candidate);next.add(new State(labels,state.cost+cost(candidate)));}}next.sort(Comparator.comparingDouble(state->state.cost));if(next.size()>10)next=new ArrayList<>(next.subList(0,10));beam=next;if(beam.isEmpty())break;}if(!beam.isEmpty()&&beam.get(0).labels.size()==order.size())return result(beam.get(0).labels,events.size());}
        // Dense fallback always keeps every event on these same four tracks, using shorter names.
        List<Label> labels=new ArrayList<>();for(int track=0;track<4;track++){List<Integer> row=new ArrayList<>();for(int i=track;i<order.size();i+=4)row.add(order.get(i));if(row.isEmpty())continue;float spacing=Math.min(gap,available/Math.max(1,row.size()*5)),limit=Math.max(1,(available-spacing*(row.size()-1))/row.size());float[] left=new float[row.size()],length=new float[row.size()];String[] names=new String[row.size()];for(int i=0;i<row.size();i++){DayEvents.Segment event=events.get(row.get(i));names[i]=name(event,paint,Math.min(maxName,limit));length[i]=Math.min(limit,Math.max(1,paint.measureText(names[i])+Math.min(gap,limit*.15f)));float anchor=pad+available*(event.start+event.end)/2880f;left[i]=Math.max(i==0?pad:left[i-1]+length[i-1]+spacing,Math.min(width-pad-length[i],anchor+spacing));}for(int i=row.size()-1;i>=0;i--)left[i]=Math.min(left[i],i==row.size()-1?width-pad-length[i]:left[i+1]-spacing-length[i]);for(int i=0;i<row.size();i++){DayEvents.Segment event=events.get(row.get(i));float anchor=pad+available*(event.start+event.end)/2880f,x=left[i],right=x+length[i],elbow=anchor<=(x+right)/2?x:right,y=(track%2==0?-1:1)*(gap*2+(track/2)*rowHeight);labels.add(make(event,row.get(i),track%2==0?-1:1,track/2,anchor,x,right,elbow,y,names[i],paint,gap));}}
        return result(labels,events.size());
    }
    private static Layout result(List<Label> labels,int next){Layout out=new Layout();out.labels.addAll(labels);out.next=next;for(Label label:labels)if(label.side<0)out.above=Math.max(out.above,label.row+1);else out.below=Math.max(out.below,label.row+1);return out;}
    private static String name(DayEvents.Segment event,TextPaint paint,float limit){return TextUtils.ellipsize(event.title.replace('\n',' '),paint,Math.max(1,limit),TextUtils.TruncateAt.END).toString();}
    private static double cost(Label label){return Math.hypot(label.elbow-label.anchor,label.y)+label.row*6;}
    private static Label make(DayEvents.Segment event,int index,int side,int row,float anchor,float left,float right,float elbow,float y,String title,TextPaint paint,float gap){float baseline=side<0?y-gap/2:y+gap/2-paint.ascent();RectF box=new RectF(left,baseline+paint.getFontMetrics().top,right,baseline+paint.getFontMetrics().bottom);box.inset(0,-gap*.2f);return new Label(event,index,side,row,anchor,left,right,elbow,y,title,box);}
    private static List<Label> candidates(DayEvents.Segment event,int index,List<Label> existing,float width,TextPaint paint,float pad,float gap,float maxName,float rowHeight){List<Label> result=new ArrayList<>();float available=Math.max(1,width-2*pad),center=pad+available*(event.start+event.end)/2880f,length=Math.min(available,Math.max(gap,paint.measureText(name(event,paint,maxName))+gap)),slant=Math.max(1,Math.min(gap*1.5f,available*.04f));String title=name(event,paint,maxName);for(float shift:new float[]{0,-gap*.6f,gap*.6f}){float anchor=Math.max(pad+available*event.start/1440f,Math.min(pad+available*event.end/1440f,center+shift));for(int row=0;row<2;row++)for(int side:new int[]{-1,1})for(int direction:new int[]{1,-1}){float wanted=direction>0?anchor+slant:anchor-slant-length;List<Float> positions=new ArrayList<>(Arrays.asList(wanted,pad,width-pad-length));for(Label old:existing)if(old.side==side&&old.row==row){positions.add(old.right+gap);positions.add(old.left-gap-length);}for(float left:positions){float right=left+length,elbow=direction>0?left:right;if(left<pad||right>width-pad+.1f||(elbow-anchor)*direction<slant-.1f)continue;Label label=make(event,index,side,row,anchor,left,right,elbow,side*(gap*2+row*rowHeight),title,paint,gap);if(clear(label,existing,gap))result.add(label);}}}return result;}
    private static boolean clear(Label a,List<Label> existing,float gap){for(Label b:existing){if(a.side!=b.side)continue;if(a.row==b.row&&a.left<b.right+gap&&a.right+gap>b.left)return false;if(RectF.intersects(a.textBounds,b.textBounds))return false;if(hit(a.anchor,0,a.elbow,a.y,b.textBounds)||hit(a.left,a.y,a.right,a.y,b.textBounds)||hit(b.anchor,0,b.elbow,b.y,a.textBounds)||hit(b.left,b.y,b.right,b.y,a.textBounds))return false;float[][] linesA={{a.anchor,0,a.elbow,a.y},{a.left,a.y,a.right,a.y}},linesB={{b.anchor,0,b.elbow,b.y},{b.left,b.y,b.right,b.y}};for(float[] x:linesA)for(float[] y:linesB)if(cross(x[0],x[1],x[2],x[3],y[0],y[1],y[2],y[3]))return false;}return true;}
    private static boolean hit(float x,float y,float ex,float ey,RectF r){if(r.contains(x,y)||r.contains(ex,ey))return true;return cross(x,y,ex,ey,r.left,r.top,r.right,r.top)||cross(x,y,ex,ey,r.right,r.top,r.right,r.bottom)||cross(x,y,ex,ey,r.right,r.bottom,r.left,r.bottom)||cross(x,y,ex,ey,r.left,r.bottom,r.left,r.top);}
    private static float orient(float ax,float ay,float bx,float by,float cx,float cy){return (bx-ax)*(cy-ay)-(by-ay)*(cx-ax);}
    private static boolean cross(float ax,float ay,float bx,float by,float cx,float cy,float dx,float dy){if(Math.max(ax,bx)<Math.min(cx,dx)-.01f||Math.max(cx,dx)<Math.min(ax,bx)-.01f||Math.max(ay,by)<Math.min(cy,dy)-.01f||Math.max(cy,dy)<Math.min(ay,by)-.01f)return false;float a=orient(ax,ay,bx,by,cx,cy),b=orient(ax,ay,bx,by,dx,dy),c=orient(cx,cy,dx,dy,ax,ay),d=orient(cx,cy,dx,dy,bx,by);return a*b<=.0001f&&c*d<=.0001f;}
}
